"""Render the Splunk app (props, transforms, tags, fields, savedsearches) from plan."""

from __future__ import annotations

from pathlib import Path

from . import plan

HEADER = (
    "# Generated by scripts/lab/splunk_setup/conf.py from plan.py — do not hand-edit.\n"
    "# Source of truth: docs/hunt/SPLUNK_SETUP_RUNBOOK.md, stage 1.\n\n"
)

#: Index-time extraction: target sourcetype -> field -> regex (FORMAT is field::$1).
#: Every stanza writes ``WRITE_META = true`` — without it Splunk keeps the value out of the tsidx.
INDEX_FIELDS: dict[str, dict[str, str]] = {
    "linux_secure": {
        #: A username never contains `"`, so the class stops the JSON shape swallowing the record.
        "user": r"(?:Failed password for (?:invalid user )?|Accepted \S+ for |for user )"
        r"([A-Za-z0-9_.@-]+)",
        "src": r"\bfrom (\d{1,3}(?:\.\d{1,3}){3})",
    },
    "linux_audit": {
        "acct": r'\bacct="([^"]*)"',
        "exe": r'\bexe="([^"]*)"',
        "addr": r'\baddr="?(\d{1,3}(?:\.\d{1,3}){3})',
        "terminal": r"\bterminal=(\S+)",
        "uid": r"\buid=(\d+)",
        "auid": r"(?:^|\s)auid=(\d+)",
    },
    #: One sourcetype for both Apache shapes: vhost_combined is combined behind `vhost:port `.
    "access_combined": {
        "c_ip": r"^(?:[^\s:]+:\d+ )?(\S+) ",
        "c_user": r"^(?:[^\s:]+:\d+ )?\S+ \S+ (\S+) \[",
        "vhost": r"^([^\s:]+):\d+ ",
        "cs_method": r'"([A-Z]+) \S+ HTTP/',
        "cs_uri_stem": r'"[A-Z]+ (\S+) HTTP/',
        "sc_status": r'" (\d{3}) ',
        "cs_user_agent": r'"([^"]*)"\s*$',
    },
    "suricata:fast": {
        "signature_id": r"\[\d+:(\d+):\d+\]",
        "signature": r"\[\d+:\d+:\d+\] ([^\[]{2,}?)\s*\[\*\*\]",
        "severity": r"\[Priority: (\d+)\]",
        "src": r"\{[A-Za-z]+\} (\d{1,3}(?:\.\d{1,3}){3}):\d+ ->",
        "dest": r"-> (\d{1,3}(?:\.\d{1,3}){3}):",
    },
    "dnsmasq": {
        "dns_query": r"query\[[A-Za-z]+\] (\S+)",
        "src": r"query\[[A-Za-z]+\] \S+ from (\S+)",
    },
}

#: JSON index-time extraction: the fields the doc names, marked INDEXED so they are never
#: re-extracted at search time.
JSON_INDEXED: dict[str, tuple[str, ...]] = {
    "suricata": (
        "event_type",
        "src_ip",
        "dest_ip",
        "src_port",
        "dest_port",
        "proto",
        "alert.signature",
        "dns.rrname",
        "http.url",
        "http.status",
        "flow.action",
    ),
}

#: Search-time CIM aliases: index-time names stay vendor-native (rule 8 of the realism doc).
EVALS: dict[str, dict[str, str]] = {
    "linux_secure": {
        "dest": "host",
        "action": 'if(match(_raw, "(?i)failed|failure|invalid"), "failure", "success")',
        "app": 'case(match(_raw, "sshd"), "sshd", match(_raw, "sudo"), "sudo", true(), "pam")',
    },
    "linux_audit": {
        "dest": "host",
        "action": 'if(match(_raw, "res=failed"), "failure", "success")',
        "process": "comm",
        "process_name": "comm",
        "process_path": "exe",
        "process_id": "pid",
        "parent_process_id": "ppid",
    },
    "dnsmasq": {
        "query": "dns_query",
        "dest": "host",
        "vendor_product": '"dnsmasq"',
    },
    "access_combined": {
        "src": "c_ip",
        "user": 'if(c_user="-", null(), c_user)',
        "dest": "host",
        "site": "vhost",
        "http_method": "cs_method",
        "uri_path": "cs_uri_stem",
        "status": "sc_status",
        "http_user_agent": "cs_user_agent",
        "action": '"allowed"',
    },
    "suricata": {
        "src": "src_ip",
        "dest": "dest_ip",
        "src_port": "src_port",
        "dest_port": "dest_port",
        "transport": "proto",
        "query": "dns.rrname",
        "bytes_in": "flow.bytes_toclient",
        "bytes_out": "flow.bytes_toserver",
        "http_method": "http.http_method",
        "uri_path": "url",
        "status": "http.status",
        "action": 'if(event_type="flow", if(flow.action="blocked", "blocked", "allowed"), null())',
    },
}

SAVEDSEARCH_CRON = "25 3 * * *"


def _slug(sourcetype: str) -> str:
    return "".join(ch if ch.isalnum() else "_" for ch in sourcetype)


def _props_stanza(st: str, tgt: plan.Target) -> dict[str, str]:
    body: dict[str, str] = {"SHOULD_LINEMERGE": "false"}
    if tgt.index_time == "json":
        body["INDEXED_EXTRACTIONS"] = "json"
        body["KV_MODE"] = "none"
        body["TRUNCATE"] = "65535"
    if st in INDEX_FIELDS:
        names = [f"ph_ix_{_slug(st)}_{field}" for field in INDEX_FIELDS[st]]
        body[f"TRANSFORMS-ph_ix_{_slug(st)}"] = ", ".join(names)
    for field, expression in EVALS.get(st, {}).items():
        body[f"EVAL-{field}"] = expression
    return body


def props_conf() -> str:
    out = [HEADER]
    for st, tgt in plan.TARGETS.items():
        if tgt.index_time == "" and st not in EVALS:
            continue
        out.append(f"[{st}]")
        out.extend(f"{k} = {v}" for k, v in _props_stanza(st, tgt).items())
        out.append("")
    return "\n".join(out)


def transforms_conf() -> str:
    out = [HEADER]
    for st, fields in INDEX_FIELDS.items():
        for field, regex in fields.items():
            out.append(f"[ph_ix_{_slug(st)}_{field}]")
            out.append(f"REGEX = {regex}")
            out.append(f"FORMAT = {field}::$1")
            out.append("WRITE_META = true")
            out.append("")
    return "\n".join(out)


def fields_conf() -> str:
    names = {field for fields in INDEX_FIELDS.values() for field in fields}
    for fields in JSON_INDEXED.values():
        names.update(fields)
    return HEADER + "".join(f"[{name}]\nINDEXED = true\n\n" for name in sorted(names))


def eventtypes_conf() -> str:
    return HEADER + "".join(
        f"[{name}]\nsearch = {search}\n\n" for name, search, _tags in plan.EVENTTYPES
    )


def tags_conf() -> str:
    out = [HEADER]
    for name, _search, tags in plan.EVENTTYPES:
        out.append(f"[eventtype={name}]")
        out.extend(f"{tag} = enabled" for tag in tags)
        out.append("")
    return "\n".join(out)


def summary_search(spec: plan.IndexSpec) -> str:
    return (
        f'index={spec.target_index} sourcetype="linux_audit" '
        f"| stats count dc(host) as hosts min(_time) as first_seen max(_time) as last_seen "
        f"by {spec.entity_field} "
        "| addinfo "
        "| collect index=summary "
        f'marker="hunt_entities_index={spec.source_index}, hunt_source={plan.APP_NAME}"'
    )


def savedsearches_conf() -> str:
    out = [HEADER]
    for spec in plan.TUNED:
        out.append(f"[{spec.summary_search}]")
        out.append(f"search = {summary_search(spec)}")
        out.append(f"cron_schedule = {SAVEDSEARCH_CRON}")
        out.append(f"dispatch.earliest_time = {plan.ACCEL_WINDOW}")
        out.append("dispatch.latest_time = now")
        out.append("enableSched = 1")
        out.append("")
    return "\n".join(out)


def app_conf() -> str:
    return (
        "[install]\nis_configured = 1\n\n"
        "[ui]\nis_visible = 0\nlabel = Portal 5 hunt setup\n\n"
        "[launch]\nauthor = portal5\nversion = 1.0.0\n"
    )


def conf_files(with_change: bool = False) -> dict[str, str]:
    """filename -> text for every conf file the app ships (CIM owns macros and acceleration)."""
    return {
        "app.conf": app_conf(),
        "props.conf": props_conf(),
        "transforms.conf": transforms_conf(),
        "fields.conf": fields_conf(),
        "eventtypes.conf": eventtypes_conf(),
        "tags.conf": tags_conf(),
        "savedsearches.conf": savedsearches_conf(),
    }


def metadata_default_meta() -> str:
    """Export every knowledge object: acceleration runs in Splunk_SA_CIM, not in this app."""
    return HEADER + "[]\naccess = read : [ * ], write : [ admin ]\nexport = system\n"


def write_app(root: Path, with_change: bool = False) -> Path:
    app_dir = root / plan.APP_NAME / "default"
    app_dir.mkdir(parents=True, exist_ok=True)
    for name, text in conf_files(with_change).items():
        (app_dir / name).write_text(text)
    metadata = root / plan.APP_NAME / "metadata"
    metadata.mkdir(parents=True, exist_ok=True)
    (metadata / "default.meta").write_text(metadata_default_meta())
    for name in plan.LEGACY_CONF_FILES:
        (app_dir / name).unlink(missing_ok=True)
    return root / plan.APP_NAME


def diff_app(root: Path, with_change: bool = False) -> list[str]:
    """Files whose committed copy differs from the renderer (empty means in sync)."""
    app_dir = root / plan.APP_NAME / "default"
    out = []
    for name, text in conf_files(with_change).items():
        path = app_dir / name
        if not path.exists() or path.read_text() != text:
            out.append(name)
    meta = root / plan.APP_NAME / "metadata" / "default.meta"
    if not meta.exists() or meta.read_text() != metadata_default_meta():
        out.append("metadata/default.meta")
    return out
